/**
 * Rebuild the incident figures of the daily and weekly reports published
 * before #176, with a dated note (see incident-reports.ts). URL, publishedAt
 * and updatedAt stay as they are; so do the fuel, weather and link sections.
 *
 *   npx tsx scripts/correct-incident-reports.ts                     # dry run
 *   npx tsx scripts/correct-incident-reports.ts --apply --expect 233
 *
 * The rows, exactly (the backup takes the same filter):
 *   status = 'PUBLISHED' AND "isAutoGenerated" = true
 *   AND category IN ('DAILY_REPORT', 'WEEKLY_REPORT')
 *   AND (slug LIKE 'informe-diario-%' OR slug LIKE 'informe-semanal-%')
 *   AND "publishedAt" < '2026-10-22T00:43:06Z'
 *
 * The dry run prints, per family, how many reports change, how many have no
 * comparison or no figures (collector outages), and sample diffs. --apply
 * refuses while any report has a structure it doesn't know, runs one
 * transaction, updates each row only if its title, summary and body are still
 * the ones read, and rolls back unless exactly --expect rows changed.
 */

import pg from "pg";
import { getPool, getPrisma } from "../shared/prisma";
import {
  countIncidents,
  dgtSeenHours,
  getProvinceNameMap,
  incidentCounts,
  reportedBySource,
} from "../tasks/insights/generators/shared";
import { dailyIncidentText, outageHours, weeklyIncidentText } from "../tasks/insights/generators/incident-text";
import { FIXED_AT, daysBefore, familyOf, reportDay, rewriteDaily, rewriteWeekly, type Family, type Rewritten } from "./incident-reports";

interface Row {
  id: string;
  slug: string;
  title: string;
  summary: string;
  body: string;
  publishedAt: Date;
}

/** The first report went out on 2-04; the pulse is read from a week before its comparison window. */
const SEEN_FROM = new Date("2026-03-15T00:00:00Z");
const HOUR = 3_600_000;

function sampleDiff(before: Row, after: Rewritten): string {
  const a = before.body.split("\n");
  const b = after.body.split("\n");
  const gone = a.filter((l) => !b.includes(l));
  const added = b.filter((l) => !a.includes(l));
  return [
    ...(after.title !== before.title ? [`  title - ${before.title}`, `  title + ${after.title}`] : []),
    `  summary - ${before.summary}`,
    `  summary + ${after.summary}`,
    ...gone.map((l) => `  - ${l}`),
    ...added.map((l) => `  + ${l}`),
  ].join("\n");
}

async function main() {
  const args = process.argv.slice(2);
  const apply = args.includes("--apply");
  const expect = Number(args[args.indexOf("--expect") + 1]);
  if (apply && !(args.includes("--expect") && Number.isInteger(expect) && expect > 0)) {
    throw new Error("--apply needs --expect <count> from the dry run");
  }
  const url = process.env.DATABASE_URL;
  if (!url) throw new Error("DATABASE_URL is not set");

  const prisma = getPrisma();
  const pool = new pg.Pool({ connectionString: url, max: 1 });
  const client = await pool.connect();
  try {
    const found = await client.query(
      `SELECT id, slug, title, summary, body, "publishedAt" FROM "Article"
       WHERE status = 'PUBLISHED' AND "isAutoGenerated" = true
         AND category IN ('DAILY_REPORT', 'WEEKLY_REPORT')
         AND (slug LIKE 'informe-diario-%' OR slug LIKE 'informe-semanal-%')
         AND "publishedAt" < $1
       ORDER BY "publishedAt"`,
      [FIXED_AT]
    );
    const rows = found.rows as Row[];

    const now = new Date();
    const [seen, provinceNames] = await Promise.all([
      dgtSeenHours(prisma, SEEN_FROM, new Date(now.getTime() + HOUR)),
      getProvinceNameMap(prisma),
    ]);

    type Stats = { read: number; change: number; same: number; refused: string[]; partial: number; noFigures: number; noComparison: number };
    const blank = (): Stats => ({ read: 0, change: 0, same: 0, refused: [], partial: 0, noFigures: 0, noComparison: 0 });
    const stats: Record<Family, Stats> = { daily: blank(), weekly: blank() };
    const samples = new Map<string, string>();
    const changes: { row: Row; next: Rewritten }[] = [];
    const sample = (key: string, row: Row, next: Rewritten) => {
      if (!samples.has(key)) samples.set(key, `${row.slug} (${row.publishedAt.toISOString()})\n${sampleDiff(row, next)}`);
    };

    for (const row of rows) {
      const family = familyOf(row.slug);
      if (!family) continue;
      const s = stats[family];
      s.read++;
      const today = reportDay(row.publishedAt);
      let next: Rewritten | null;
      let kind: string;

      if (family === "daily") {
        const dayStart = daysBefore(today, 1);
        const weekStart = daysBefore(today, 8);
        const [yesterday, weekBefore] = await Promise.all([
          incidentCounts(prisma, dayStart, today),
          reportedBySource(prisma, weekStart, dayStart),
        ]);
        const missing = { day: outageHours(seen, dayStart, today, now), weekBefore: outageHours(seen, weekStart, dayStart, now) };
        const text = dailyIncidentText({ yesterday, weekBefore, missing, provinceNames, active: null, withCitySensors: false });
        next = rewriteDaily(row, text);
        kind = missing.day >= 12 ? "noFigures" : missing.day > 0 ? "partial" : missing.weekBefore > 0 ? "noComparison" : "full";
      } else {
        const weekStart = daysBefore(today, 7);
        const lastWeekStart = daysBefore(today, 14);
        const days = Array.from({ length: 7 }, (_, i) => ({ start: daysBefore(today, 7 - i), end: daysBefore(today, 6 - i) }));
        const [week, lastWeekBySource, perDay] = await Promise.all([
          incidentCounts(prisma, weekStart, today),
          reportedBySource(prisma, lastWeekStart, weekStart),
          Promise.all(days.map((d) => countIncidents(prisma, d.start, d.end))),
        ]);
        const missing = { week: outageHours(seen, weekStart, today, now), lastWeek: outageHours(seen, lastWeekStart, weekStart, now) };
        const text = weeklyIncidentText({
          week,
          lastWeekBySource,
          perDay: days.map((d, i) => ({ dateStart: d.start, incidentTotal: perDay[i], missingHours: outageHours(seen, d.start, d.end, now) })),
          v16Activations: null,
          missing,
          provinceNames,
          withCitySensors: false,
        });
        next = rewriteWeekly(row, text);
        kind = missing.week >= 84 ? "noFigures" : missing.week > 0 ? "partial" : missing.lastWeek > 0 ? "noComparison" : "full";
      }

      if (!next) {
        s.refused.push(row.slug);
        continue;
      }
      if (next.body === row.body && next.summary === row.summary && next.title === row.title) {
        s.same++;
        continue;
      }
      s.change++;
      if (kind === "noFigures") s.noFigures++;
      else if (kind === "partial") s.partial++;
      else if (kind === "noComparison") s.noComparison++;
      changes.push({ row, next });
      sample(`${family}, ${kind}`, row, next);
    }

    for (const [family, s] of Object.entries(stats)) {
      console.log(
        `${family}: ${s.read} read, ${s.change} to correct, ${s.same} already correct, ${s.refused.length} refused` +
          ` (of those to correct: ${s.partial} with an outage, ${s.noFigures} without figures, ${s.noComparison} without comparison)`
      );
      for (const slug of s.refused.slice(0, 5)) console.log(`  refused: ${slug}`);
    }
    for (const [key, diff] of samples) console.log(`\nsample (${key}): ${diff}`);
    const refused = Object.values(stats).reduce((n, s) => n + s.refused.length, 0);
    console.log(`\ntotal to correct: ${changes.length}`);

    if (!apply) {
      console.log(`dry run: nothing written. Apply with --apply --expect ${changes.length}`);
      return;
    }
    if (refused > 0) throw new Error(`${refused} reports have a structure this doesn't know: handle them first`);

    await client.query("BEGIN");
    let updated = 0;
    for (const { row, next } of changes) {
      const r = await client.query(
        `UPDATE "Article" SET title = $1, summary = $2, body = $3
         WHERE id = $4 AND title = $5 AND summary = $6 AND body = $7 AND status = 'PUBLISHED'`,
        [next.title, next.summary, next.body, row.id, row.title, row.summary, row.body]
      );
      updated += r.rowCount ?? 0;
    }
    if (updated !== expect) {
      await client.query("ROLLBACK");
      throw new Error(`would correct ${updated}, expected ${expect}: rolled back`);
    }
    await client.query("COMMIT");
    console.log(`corrected ${updated} (committed ${new Date().toISOString()})`);
  } catch (err) {
    await client.query("ROLLBACK").catch(() => {});
    throw err;
  } finally {
    client.release();
    await pool.end();
    await prisma.$disconnect();
    await getPool()?.end();
  }
}

main().catch((err) => {
  console.error(err instanceof Error ? err.message : err);
  process.exit(1);
});
